"""Fixed SQL only; never execute SQL generated by the model."""
from datetime import timedelta
from pathlib import Path

from psycopg.types.json import Jsonb

from competitor_db import connect


def load_snapshot(settings, now):
    start = now.date()
    end = start + timedelta(days=settings.horizon_days)
    cutoff = now - timedelta(days=settings.freshness_days)
    with connect() as conn:
        conn.execute("SET TRANSACTION READ ONLY")
        conn.execute("SET LOCAL statement_timeout = '30s'")
        # Scope BEFORE deduplication: the global latest view can mix own hotels.
        rows = conn.execute("""
            WITH latest AS (
                SELECT DISTINCT ON (p.hotel_key, p.stay_date, p.adults,
                                    p.children_ages, p.rooms_requested) p.*
                FROM daily_hotel_prices p
                JOIN collection_batches b ON b.id=p.batch_id
                JOIN collection_queries q ON q.id=p.query_id
                WHERE b.own_hotel=%s AND b.status='succeeded' AND q.status='stored'
                  AND p.stay_date >= %s AND p.stay_date < %s
                  AND p.collected_at >= %s AND p.collected_at <= %s
                  AND p.nightly_jpy > 0 AND p.currency='JPY'
                ORDER BY p.hotel_key, p.stay_date, p.adults, p.children_ages,
                         p.rooms_requested, p.collected_at DESC, p.id DESC
            )
            SELECT stay_date, adults, children_ages, rooms_requested,
                   count(*), min(nightly_jpy),
                   percentile_cont(0.5) WITHIN GROUP (ORDER BY nightly_jpy),
                   max(nightly_jpy), min(collected_at), max(collected_at)
            FROM latest
            GROUP BY stay_date, adults, children_ages, rooms_requested
            ORDER BY stay_date, adults, children_ages, rooms_requested
            LIMIT 501
        """, (settings.hotel, start, end, cutoff, now)).fetchall()
    if len(rows) > 500:
        raise ValueError("报价分组超过500，请缩短 MARKETING_HORIZON_DAYS")
    groups = [dict(evidence_id=f"price-{i:03d}", stay_date=str(r[0]), adults=r[1],
                   children_ages=r[2], rooms=r[3], hotel_count=r[4],
                   min_jpy=float(r[5]), median_jpy=float(r[6]), max_jpy=float(r[7]),
                   oldest_observation=r[8].isoformat(), newest_observation=r[9].isoformat())
              for i, r in enumerate(rows, 1)]
    return dict(own_hotel=settings.hotel, as_of=now.isoformat(), currency="JPY",
                window_start=str(start), window_end_exclusive=str(end), groups=groups,
                limitations=["仅包含成功采集批次中的近期单晚报价，缺报价不等于售罄。",
                             "报价不代表成交价，税费与房型可比性、实际入住容量仍需核对。",
                             "未接入本店订单、库存、成本、营销预算和活动效果，不能计算入住率、利润或营销ROI。",
                             "分组为同入住日、成人数、儿童年龄及房间数；不能跨组直接比较。"])


class ReportStore:
    def __init__(self, hotel):
        self.hotel = hotel

    @staticmethod
    def initialize():
        with connect() as conn:
            conn.execute((Path(__file__).resolve().parents[1] / "sql/004_a_marketing_reports.sql").read_text(encoding="utf-8"))
            conn.execute((Path(__file__).resolve().parents[1] / "sql/005_a_report_emails.sql").read_text(encoding="utf-8"))

    def get(self, key):
        with connect() as conn:
            row = conn.execute("SELECT run_key,status,payload FROM a_marketing_reports WHERE own_hotel=%s AND run_key=%s",
                               (self.hotel, key)).fetchone()
        return dict(run_key=row[0], status=row[1], payload=row[2]) if row else None

    def claim_email(self, key, recipient, retry=False):
        with connect() as conn:
            row = conn.execute("""INSERT INTO a_report_emails(own_hotel,run_key,recipient,status)
                VALUES (%s,%s,%s,'sending') ON CONFLICT (own_hotel,run_key) DO UPDATE
                SET status='sending',recipient=EXCLUDED.recipient,error_type=NULL,updated_at=now()
                WHERE a_report_emails.status='failed' AND %s RETURNING run_key""",
                (self.hotel, key, recipient, retry)).fetchone()
        return row is not None

    def finish_email(self, key, status, error_type=None):
        with connect() as conn:
            conn.execute("""UPDATE a_report_emails SET status=%s,error_type=%s,updated_at=now()
                WHERE own_hotel=%s AND run_key=%s""", (status, error_type, self.hotel, key))

    def claim(self, key):
        with connect() as conn:
            row = conn.execute("""INSERT INTO a_marketing_reports(own_hotel,run_key,status,payload)
                VALUES (%s, %s, 'running', '{}'::jsonb)
                ON CONFLICT (own_hotel,run_key) DO NOTHING RETURNING id""", (self.hotel, key)).fetchone()
            return row is not None

    def save(self, key, status, payload):
        with connect() as conn:
            cursor = conn.execute("""UPDATE a_marketing_reports
                SET status=%s,payload=%s,updated_at=CURRENT_TIMESTAMP
                WHERE own_hotel=%s AND run_key=%s""", (status, Jsonb(payload), self.hotel, key))
            if cursor.rowcount != 1:
                raise LookupError("营销运行记录不存在")

    def latest(self):
        with connect() as conn:
            row = conn.execute("""SELECT run_key,status,payload FROM a_marketing_reports
                WHERE own_hotel=%s ORDER BY id DESC LIMIT 1""", (self.hotel,)).fetchone()
        return dict(run_key=row[0], status=row[1], payload=row[2]) if row else None
